        @test bandwidths(b .* A) == bandwidths(A)
        @test A .* b == Matrix(A) .* b
        @test A .* b isa BandedMatrix
        @test bandwidths(A .* b) == bandwidths(A)
        @test b .\ A == b .\ Matrix(A)
        @test b .\ A isa BandedMatrix
        @test bandwidths(b .\ A) == bandwidths(A)
        @test A ./ b == Matrix(A) ./ b
        @test A ./ b isa BandedMatrix
