go
func (r *Reader) NextFile() (*zip.File, error) {
	if len(r.unread) == 0 {
		if len(r.File) == 0 {
			return nil, io.EOF
		}
		r.unread = r.File
		r.File = nil
	}

	file := r.unread[0]
	r.unread = r.unread[1:]

	rc, err := file.Open()
	if err != nil {
		return nil, err
	}
	r.rc = rc

	return file, nil
}

// ReadFile reads the content of the current file in the zip archive.
func (r *Reader) ReadFile(b []byte) (int, error) {
	if r.rc == nil {
		return 0, io.EOF
	}
	return r.rc.Read(b)
}

// Close closes the current file's reader.
func (r *Reader) Close() error {
	if r.rc != nil {
		err := r.rc.Close()
		r.rc = nil
		return err
	}
	return nil
}

