// GenerateBootstrapConfig generates the Envoy bootstrap configuration based on the BootstrapConfig.
func (c *BootstrapConfig) GenerateBootstrapConfig() (string, error) {
	tmpl, err := template.New("bootstrap").Parse(c.Template())
	if err != nil {
		return "", fmt.Errorf("failed to parse bootstrap template: %w", err)
	}

	var buf bytes.Buffer
	if err := tmpl.Execute(&buf, c); err != nil {
		return "", fmt.Errorf("failed to execute bootstrap template: %w", err)
	}

	return buf.String(), nil
}

