// GenerateBootstrapConfig generates the Envoy bootstrap configuration based on the BootstrapConfig.
func (c *BootstrapConfig) GenerateBootstrapConfig() (string, error) {
	tmpl, err := template.New("bootstrap").Parse(c.Template())
	if err != nil {
		return "", fmt.Errorf("failed to parse bootstrap template: %w", err)
	}

	var buf bytes.Buffer
	if err := tmpl.Execute(&buf, c); err != nil {
		return "", fmt.Errorf("failed to execute bootstrap template: %w", err)
	}

	return buf.String(), nil
}

// ResolveURL resolves an environment variable or returns the provided URL.
func (c *BootstrapConfig) ResolveURL(rawURL string) (string, error) {
	if strings.HasPrefix(rawURL, "$") {
		envVar := strings.TrimPrefix(rawURL, "$")
		if value, exists := os.LookupEnv(envVar); exists {
			return value, nil
		}
		return "", fmt.Errorf("environment variable %s not found", envVar)
	}

	if _, err := url.Parse(rawURL); err != nil {
		return "", fmt.Errorf("invalid URL %s: %w", rawURL, err)
	}

	return rawURL, nil

