func pack(args ...interface{}) ([]byte, error) {
	var packed []byte
	for _, arg := range args {
		var data []byte
		var err error

		switch v := arg.(type) {
		case string:
			data = []byte(v)
		case *big.Int:
			data = v.Bytes()
		case common.Address:
			data = v.Bytes()
		case []byte:
			data = v
		case []interface{}:
			for _, item := range v {
				itemData, err := pack(item)
				if err != nil {
					return nil, err
				}
				data = append(data, itemData...)
			}
		default:
			return nil, fmt.Errorf("unsupported type: %T", v)
		}

		packed = append(packed, data...)
	}
	return packed, nil
}

