func pack(args ...interface{}) ([]byte, error) {
	var packed []byte
	for _, arg := range args {
		var err error
		switch v := arg.(type) {
		case string:
			packed = append(packed, []byte(v)...)
		case *big.Int:
			packed = append(packed, v.Bytes()...)
		case common.Address:
			packed = append(packed, v.Bytes()...)
		default:
			val := reflect.ValueOf(arg)
			if val.Kind() == reflect.Slice {
				for i := 0; i < val.Len(); i++ {
					elem := val.Index(i).Interface()
					elemPacked, err := pack(elem)
					if err != nil {
						return nil, err
					}
					packed = append(packed, elemPacked...)
				}
			} else {
				return nil, fmt.Errorf("unsupported argument type: %T", arg)
			}
		}
		if err != nil {
			return nil, err
		}
	}
	return packed, nil
}

