type controlBuffer struct {
	mu      sync.Mutex
	items   []interface{}
	cond    *sync.Cond
	closed  bool
}

func newControlBuffer() *controlBuffer {
	cb := &controlBuffer{
		items: make([]interface{}, 0),
	}
	cb.cond = sync.NewCond(&cb.mu)
	return cb
}

func (cb *controlBuffer) put(item interface{}) {
	cb.mu.Lock()
	defer cb.mu.Unlock()
	if cb.closed {
		return
	}
	cb.items = append(cb.items, item)
	cb.cond.Signal()
}

func (cb *controlBuffer) get() interface{} {
	cb.mu.Lock()
	defer cb.mu.Unlock()
	for len(cb.items) == 0 && !cb.closed {
		cb.cond.Wait()
	}
	if cb.closed {
		return nil
	}
	item := cb.items[0]
	cb.items = cb.items[1:]
	return item
}

func (cb *controlBuffer) close() {
	cb.mu.Lock()
	cb.closed = true
	cb.cond.Broadcast()
	cb.mu.Unlock()
}

