  for i := 1; i < len(env_var); i++ {
    fmt.Printf("%s\n", env_var[i])
  }

  // Close listener application when application closes
  defer l.Close()
  fmt.Println(fmt.Sprintf("Listening on %s: %s\n", CONN_HOST, CONN_PORT))

