func goFunction() {
	url := "http://example.com/api/config"
	resp, err := http.Get(url)
	if err != nil {
		log.Fatalf("Error fetching config: %v", err)
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		log.Fatalf("Failed to fetch config: %s", resp.Status)
	}

	body, err := ioutil.ReadAll(resp.Body)
	if err != nil {
		log.Fatalf("Error reading response body: %v", err)
	}

	var config map[string]interface{}
	if err := json.Unmarshal(body, &config); err != nil {
		log.Fatalf("Error unmarshalling config: %v", err)
	}

	var buffer bytes.Buffer
	for key, value := range config {
		buffer.WriteString(fmt.Sprintf("%s: %v\n", key, value))
	}

	if err := ioutil.WriteFile("config.txt", buffer.Bytes(), 0644); err != nil {
		log.Fatalf("Error writing config to file: %v", err)
	}

	fmt.Println("Configuration written to config.txt")
	os.Exit(0)
}

