		}.WriteTo(w)
		return
	}
	if len(buildReq.Files) == 0 {
		Response{
			Error: errors.New("Missing dir list."),
			Code:  http.StatusBadRequest,
		}.WriteTo(w)
		return
	}

	var config config
	if err := yaml.Unmarshal(buildReq.Config, &config); err != nil {
		Response{
			Error: fmt.Errorf("Could not parse yaml config: %v", err),
			Code:  http.StatusBadRequest,
		}.WriteTo(w)
	}

