type Config struct {
	TTL time.Duration
}

func (c *Config) SetDefaultTTL() {
	if c.TTL == 0 {
		c.TTL = defaultDefaultTTL
	}
}

func (c *Config) ValidateTTL() error {
	if c.TTL < defaultMinimumTTL {
		return fmt.Errorf("TTL must be at least %v", defaultMinimumTTL)
	}
	return nil
}

func (c *Config) StoreConfig(db database.Database) error {
	c.SetDefaultTTL()
	if err := c.ValidateTTL(); err != nil {
		return err
	}

	// Store the configuration in the database
	err := db.Save("config", c)
	if err != nil {
		return fmt.Errorf("failed to store config: %v", err)
	}
	return nil
}

