type ConfigStore struct {
	db database.Database
}

func NewConfigStore(db database.Database) *ConfigStore {
	return &ConfigStore{db: db}
}

func (cs *ConfigStore) GetConfig(key string) (interface{}, error) {
	return cs.db.Get(key)
}

func (cs *ConfigStore) SetConfig(key string, value interface{}, ttl time.Duration) error {
	if ttl < defaultMinimumTTL {
		ttl = defaultMinimumTTL
	} else if ttl > defaultDefaultTTL {
		ttl = defaultDefaultTTL
	}
	return cs.db.Set(key, value, ttl)
}

func (cs *ConfigStore) DeleteConfig(key string) error {
	return cs.db.Delete(key)
}

